`timescale 1ns / 1ps

// ============================================================================
// Testbench: tb_systolic_gemm.sv
// Description: Automated Self-Checking Verification Testbench for Parameterized
//              INT8 Systolic Array GEMM Accelerator.
//              - Loads input test matrices generated by Python Golden Model.
//              - Feeds Accelerator via host write interface.
//              - Automates cycle-accurate scoreboard check against Python Golden Reference.
//              - Reports comprehensive verification score and bit-true metrics.
// ============================================================================

module tb_systolic_gemm;

    localparam ARRAY_SIZE = 4;
    localparam DATA_WIDTH = 8;
    localparam ACC_WIDTH  = 32;
    localparam K_DIM      = 4;
    localparam TOTAL_C    = ARRAY_SIZE * ARRAY_SIZE;

    // Clock & Reset
    logic clk;
    logic rst_n;

    // Control & Status
    logic       start;
    logic [7:0] k_dim;
    logic       bypass_relu;
    logic [4:0] shift_bits;
    logic       done;
    logic       busy;

    // Host Interfaces
    logic                                     wr_a_en;
    logic [$clog2(ARRAY_SIZE*16)-1:0]         wr_a_addr;
    logic signed [DATA_WIDTH-1:0]             wr_a_data;

    logic                                     wr_b_en;
    logic [$clog2(ARRAY_SIZE*16)-1:0]         wr_b_addr;
    logic signed [DATA_WIDTH-1:0]             wr_b_data;

    logic [$clog2(ARRAY_SIZE*ARRAY_SIZE)-1:0] rd_c_addr;
    logic signed [DATA_WIDTH-1:0]             rd_c_data;
    logic signed [ACC_WIDTH-1:0]              rd_c_acc_data;

    // Golden model memories
    logic [DATA_WIDTH-1:0] gold_matrix_a [0:ARRAY_SIZE*K_DIM-1];
    logic [DATA_WIDTH-1:0] gold_matrix_b [0:K_DIM*ARRAY_SIZE-1];
    logic [ACC_WIDTH-1:0]  gold_acc_c    [0:TOTAL_C-1];
    logic [DATA_WIDTH-1:0] gold_quant_c  [0:TOTAL_C-1];

    // DUT Instantiation
    systolic_accelerator_top #(
        .ARRAY_SIZE (ARRAY_SIZE),
        .DATA_WIDTH (DATA_WIDTH),
        .ACC_WIDTH  (ACC_WIDTH)
    ) dut (
        .clk           (clk),
        .rst_n         (rst_n),
        .start         (start),
        .k_dim         (k_dim),
        .bypass_relu   (bypass_relu),
        .shift_bits    (shift_bits),
        .done          (done),
        .busy          (busy),
        .wr_a_en       (wr_a_en),
        .wr_a_addr     (wr_a_addr),
        .wr_a_data     (wr_a_data),
        .wr_b_en       (wr_b_en),
        .wr_b_addr     (wr_b_addr),
        .wr_b_data     (wr_b_data),
        .rd_c_addr     (rd_c_addr),
        .rd_c_data     (rd_c_data),
        .rd_c_acc_data (rd_c_acc_data)
    );

    // Clock Generation: 50 MHz (20ns period)
    always #10 clk = ~clk;

    integer i, errors;

    initial begin
        $dumpfile("systolic_gemm_waveform.vcd");
        $dumpvars(0, tb_systolic_gemm);

        clk         = 1'b0;
        rst_n       = 1'b0;
        start       = 1'b0;
        k_dim       = K_DIM;
        bypass_relu = 1'b0;
        shift_bits  = 5'd4;
        wr_a_en     = 1'b0;
        wr_b_en     = 1'b0;
        wr_a_addr   = '0;
        wr_b_addr   = '0;
        wr_a_data   = '0;
        wr_b_data   = '0;
        rd_c_addr   = '0;
        errors      = 0;

        // 1. Load Golden Test Vectors from Python
        $readmemh("matrix_a.hex", gold_matrix_a);
        $readmemh("matrix_b.hex", gold_matrix_b);
        $readmemh("golden_acc_int32.hex", gold_acc_c);
        $readmemh("golden_output_int8.hex", gold_quant_c);

        $display("\n==================================================================");
        $display("   TESTBENCH: PARAMETERIZED 2D SYSTOLIC ARRAY GEMM ACCELERATOR    ");
        $display("   Configuration: ARRAY_SIZE = %0d, K_DIM = %0d, INT8 x INT8      ", ARRAY_SIZE, K_DIM);
        $display("==================================================================");

        // Reset Sequence
        #40;
        rst_n = 1'b1;
        #20;

        // 2. Load Matrix A into Buffer A
        $display("[*] Loading Matrix A (Weights) into Buffer A...");
        for (i = 0; i < ARRAY_SIZE * K_DIM; i = i + 1) begin
            @(posedge clk);
            wr_a_en   = 1'b1;
            wr_a_addr = i;
            wr_a_data = gold_matrix_a[i];
        end
        @(posedge clk);
        wr_a_en = 1'b0;

        // 3. Load Matrix B into Buffer B
        $display("[*] Loading Matrix B (Activations) into Buffer B...");
        for (i = 0; i < K_DIM * ARRAY_SIZE; i = i + 1) begin
            @(posedge clk);
            wr_b_en   = 1'b1;
            wr_b_addr = i;
            wr_b_data = gold_matrix_b[i];
        end
        @(posedge clk);
        wr_b_en = 1'b0;

        // 4. Start Systolic Matrix Multiplication
        #20;
        $display("[*] Launching Systolic Array GEMM Execution (C = A x B)...");
        @(posedge clk);
        start = 1'b1;
        @(posedge clk);
        start = 1'b0;

        // 5. Wait for Computation & Quantized Readout to finish
        wait (done == 1'b1);
        $display("[+] Hardware execution finished! Reading out results...\n");

        // 6. Scoreboard Comparison against Python Golden Model
        $display("--- SCOREBOARD COMPARISON TABLE ---");
        $display("| Element | HW Acc (INT32) | Gold Acc | HW Out (INT8) | Gold Out | Status |");
        $display("|---------|----------------|----------|---------------|----------|--------|");

        for (i = 0; i < TOTAL_C; i = i + 1) begin
            rd_c_addr = i;
            #5; // Wait for memory read propagation

            if ((signed'(rd_c_acc_data) !== signed'(gold_acc_c[i])) || 
                (signed'(rd_c_data) !== signed'(gold_quant_c[i]))) begin
                $display("| C[%0d][%0d]  | %14d | %8d | %13d | %8d | [FAIL] |",
                         i / ARRAY_SIZE, i % ARRAY_SIZE, 
                         signed'(rd_c_acc_data), signed'(gold_acc_c[i]),
                         signed'(rd_c_data), signed'(gold_quant_c[i]));
                errors = errors + 1;
            end else begin
                $display("| C[%0d][%0d]  | %14d | %8d | %13d | %8d | [PASS] |",
                         i / ARRAY_SIZE, i % ARRAY_SIZE, 
                         signed'(rd_c_acc_data), signed'(gold_acc_c[i]),
                         signed'(rd_c_data), signed'(gold_quant_c[i]));
            end
        end

        $display("------------------------------------------------------------------");
        if (errors == 0) begin
            $display("==================================================================");
            $display("  VERIFICATION RESULT: ALL %0d ELEMENTS PASSED (0 ERRORS)!       ", TOTAL_C);
            $display("  100%% BIT-FOR-BIT MATCH WITH PYTHON GOLDEN MODEL!                ");
            $display("==================================================================");
        end else begin
            $display("==================================================================");
            $display("  VERIFICATION RESULT: FAILED WITH %0d ERRORS!                     ", errors);
            $display("==================================================================");
        end

        #100;
        $finish;
    end

endmodule
